CREATE TABLE IF NOT EXISTS users (id INTEGER PRIMARY KEY AUTOINCREMENT, username TEXT NOT NULL UNIQUE, email TEXT NOT NULL UNIQUE, password_hash TEXT NOT NULL, full_name TEXT, avatar TEXT, role TEXT NOT NULL CHECK(role IN ('student','lecturer','admin')), created_at DATETIME DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS faculties (id INTEGER PRIMARY KEY AUTOINCREMENT, name TEXT NOT NULL UNIQUE, description TEXT);
CREATE TABLE IF NOT EXISTS majors (id INTEGER PRIMARY KEY AUTOINCREMENT, faculty_id INTEGER NOT NULL, name TEXT NOT NULL, description TEXT, FOREIGN KEY(faculty_id) REFERENCES faculties(id) ON DELETE CASCADE, UNIQUE(faculty_id,name));
CREATE TABLE IF NOT EXISTS subjects (id INTEGER PRIMARY KEY AUTOINCREMENT, faculty_id INTEGER NOT NULL, name TEXT NOT NULL, description TEXT, FOREIGN KEY(faculty_id) REFERENCES faculties(id) ON DELETE CASCADE, UNIQUE(faculty_id,name));
CREATE TABLE IF NOT EXISTS major_subjects (major_id INTEGER NOT NULL, subject_id INTEGER NOT NULL, PRIMARY KEY(major_id,subject_id), FOREIGN KEY(major_id) REFERENCES majors(id) ON DELETE CASCADE, FOREIGN KEY(subject_id) REFERENCES subjects(id) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS lectures (id INTEGER PRIMARY KEY AUTOINCREMENT, title TEXT NOT NULL, description TEXT, thumbnail_url TEXT, video_url TEXT NOT NULL, duration INTEGER NOT NULL DEFAULT 0 CHECK(duration >= 0), subject_id INTEGER NOT NULL, uploaded_by INTEGER, views INTEGER NOT NULL DEFAULT 0 CHECK(views >= 0), status TEXT NOT NULL DEFAULT 'published' CHECK(status IN ('draft','published')), created_at DATETIME DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(subject_id) REFERENCES subjects(id) ON DELETE RESTRICT, FOREIGN KEY(uploaded_by) REFERENCES users(id) ON DELETE SET NULL);
CREATE TABLE IF NOT EXISTS bookmarks (id INTEGER PRIMARY KEY AUTOINCREMENT, user_id INTEGER NOT NULL, lecture_id INTEGER NOT NULL, created_at DATETIME DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE, FOREIGN KEY(lecture_id) REFERENCES lectures(id) ON DELETE CASCADE, UNIQUE(user_id,lecture_id));
CREATE TABLE IF NOT EXISTS watch_history (id INTEGER PRIMARY KEY AUTOINCREMENT, user_id INTEGER NOT NULL, lecture_id INTEGER NOT NULL, watched_seconds INTEGER NOT NULL DEFAULT 0 CHECK(watched_seconds >= 0), progress REAL NOT NULL DEFAULT 0 CHECK(progress >= 0 AND progress <= 100), is_completed BOOLEAN NOT NULL DEFAULT 0 CHECK(is_completed IN (0,1)), last_watched DATETIME DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE, FOREIGN KEY(lecture_id) REFERENCES lectures(id) ON DELETE CASCADE, UNIQUE(user_id,lecture_id));
CREATE INDEX IF NOT EXISTS idx_majors_faculty ON majors(faculty_id);
CREATE INDEX IF NOT EXISTS idx_subjects_faculty ON subjects(faculty_id);
CREATE INDEX IF NOT EXISTS idx_lectures_subject ON lectures(subject_id);
CREATE INDEX IF NOT EXISTS idx_lectures_uploaded_by ON lectures(uploaded_by);
CREATE INDEX IF NOT EXISTS idx_bookmarks_user ON bookmarks(user_id);
CREATE INDEX IF NOT EXISTS idx_history_user ON watch_history(user_id);
